#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bilnov M1 FINAL : finalise le module commentaires unifies. Ajoute pieces jointes (R2), mentions @, edition/suppression de messages, gestion des affectations, export CSV, + lien de navigation. Superseder 06. Additif. A appliquer apres 05."""
import base64, json, os, sys, subprocess
FILES={"src/lib/mentions.ts": "", "src/lib/__tests__/mentions.test.ts": "", "src/app/api/comments/[cid]/attachments/route.ts": "", "src/app/api/comment-messages/[mid]/route.ts": "", "src/app/api/projects/[id]/comments/export/csv/route.ts": "", "src/app/api/comments/[cid]/messages/route.ts": "", "src/app/projects/[id]/comments/page.tsx": ""}
EDITS=[["src/app/projects/[id]/page.tsx", "tab-type", "fCAnY29tbWVudHMnOw==", "dHlwZSBUYWIgPSAnZmlsZXMnIHwgJ3RvdXJzJyB8ICd0ZWFtJyB8ICdhY2Nlc3MnOw==", "dHlwZSBUYWIgPSAnZmlsZXMnIHwgJ3RvdXJzJyB8ICd0ZWFtJyB8ICdhY2Nlc3MnIHwgJ2NvbW1lbnRzJzs="], ["src/app/projects/[id]/page.tsx", "tab-entry", "a2V5OiAnY29tbWVudHMnLCBsYWJlbDogJ0NvbW1lbnRhaXJlcyc=", "ICAgIHsga2V5OiAnYWNjZXNzJywgbGFiZWw6ICdQYXJ0YWdlJywgaWNvbjogJ/CflJcnIH0s", "ICAgIHsga2V5OiAnYWNjZXNzJywgbGFiZWw6ICdQYXJ0YWdlJywgaWNvbjogJ/CflJcnIH0sCiAgICB7IGtleTogJ2NvbW1lbnRzJywgbGFiZWw6ICdDb21tZW50YWlyZXMnLCBpY29uOiAn8J+SrCcgfSw="], ["src/app/projects/[id]/page.tsx", "tab-content", "dGFiID09PSAnY29tbWVudHMnICYm", "ICAgICAgICA8L21haW4+", ""]]
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def write_files(root):
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
def patch(root):
    cache={}; ap=sk=0
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read(); marker,old,new=d(dm),d(o),d(nw)
        if marker in src: print("  = deja",name); cache[p]=src; sk+=1; continue
        if old not in src: print("!! ANCRE KO:",name,"@",f); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; ap+=1; print("  ~ patche",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    print("  ->",ap,"patche(s),",sk,"deja.")
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:])
    print("== Bilnov M1 FINAL =="); write_files(root); patch(root)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Bilnov M1 FINAL applique. Aucun git push.")
if __name__=='__main__': main()
